metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses and buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop for browsing and buying books" {
            webStore = container "Web Store" "Lets customers browse the catalogue and place orders" "Web application"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Service"
        }

        customer -> webStore "Browses the catalogue and places orders" "HTTPS/REST"
        webStore -> orderProcessor "Submits new orders for processing" "gRPC"
    }

    views {
        systemContext bookshop "SystemContext" "Shows the Bookshop system and its relationship with the Customer" {
            include *
            autoLayout
        }
    }
}
